<?php
require __DIR__.'/../app/bootstrap.php'; require_role(['admin']);
$search=trim((string)($_GET['q']??''));$page=max(1,(int)($_GET['page']??1));$per=25;$where='';$args=[];if($search!==''){$where='WHERE full_name LIKE ? OR personnel_code LIKE ? OR department LIKE ? OR position LIKE ?';$like='%'.$search.'%';$args=[$like,$like,$like,$like];}$q=db()->prepare("SELECT * FROM personnel {$where} ORDER BY full_name LIMIT {$per} OFFSET ".(($page-1)*$per));$q->execute($args);$rows=$q->fetchAll();$cq=db()->prepare("SELECT COUNT(*) FROM personnel {$where}");$cq->execute($args);$total=(int)$cq->fetchColumn();$pages=max(1,(int)ceil($total/$per));$page=min($page,$pages);
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>پرسنل</title><link rel="stylesheet" href="assets/app.css"></head><body><header><a class="brand" href="index.php">سامانه سخت‌افزار</a><nav><a href="index.php">داشبورد</a><a href="assets.php">تجهیزات</a><a href="directory.php">Active Directory</a><a href="users.php">کاربران برداشت</a><a href="audit.php">رویدادها</a><a href="logout.php">خروج</a></nav></header><main><div class="page-head"><div><h1>پرسنل</h1><p class="muted">این فهرست از Active Directory همگام می‌شود و مبنای انتخاب مسئول تجهیزات است.</p></div><a class="btn primary" href="directory.php">تنظیم / همگام‌سازی AD</a></div><section class="panel"><form class="search"><input name="q" value="<?=e($search)?>" placeholder="جستجوی نام، کد، اداره یا سمت"><button class="btn">جستجو</button></form><div class="table-wrap"><table><thead><tr><th>نام</th><th>کد پرسنلی</th><th>اداره / دانشکده</th><th>سمت</th><th>منبع</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?></td><td><?=e($r['personnel_code']?:'—')?></td><td><?=e($r['department']?:'—')?></td><td><?=e($r['position']?:'—')?></td><td>Active Directory</td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="empty">رکوردی یافت نشد؛ ابتدا اتصال و همگام‌سازی AD را بررسی کنید.</td></tr><?php endif;?></tbody></table></div><div class="pagination"><span>صفحه <?=$page?> از <?=$pages?> — <?=$total?> نفر</span><?php if($page>1):?><a href="?<?=e(http_build_query(array_merge($_GET,['page'=>$page-1])))?>">قبلی</a><?php endif;?><?php if($page<$pages):?><a href="?<?=e(http_build_query(array_merge($_GET,['page'=>$page+1])))?>">بعدی</a><?php endif;?></div></section></main></body></html>
